    private static Values Entry<T>(double[] baseline, double[] upgrade, string?[] fields, int mask)
        where T : CardModel => new(baseline, upgrade, fields.Select(name => name is null ? null :
            typeof(T).GetField(name, BindingFlags.Instance | BindingFlags.Static | BindingFlags.NonPublic)
                ?? throw new InvalidOperationException($"Verified card-choice field {typeof(T).Name}.{name} disappeared.")).ToArray(), mask);

    public static double Get(CardModel card, string key)
    {
        int index = key switch { "Damage" => 0, "Block" => 1, "Cards" => 2, "Energy" => 3, "Stars" => 4,
            _ => throw new ArgumentOutOfRangeException(nameof(key)) };
        if (card is ICardChoiceBaseValueProvider { CardChoiceBaseValues: { } declared })
            return declared.GetBaseValue(key);
        if (!Metadata.TryGetValue(card.GetType(), out Values? values))
            throw new InvalidOperationException($"No verified canonical {key} value for {card.GetType().FullName}; declare source literal values through ICardChoiceBaseValueProvider.");
        if ((values.PresentMask & (1 << index)) == 0) return 0d;
        return values.Fields[index] is { } field
            ? Convert.ToDouble(field.GetValue(card), CultureInfo.InvariantCulture)
            : values.Base[index] + values.Upgrade[index] * card.CurrentUpgradeLevel;
    }
